answer:
def first_unique(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    for x in items:
        if counts[x] == 1:
            return x
    return None

print(first_unique(["a", "b", "a", "c", "b"]))

